function syncFullscreen(){const on=pageFullscreen||fullscreenElement()===$('city-viewport');$('city-fullscreen').textContent=on?'Exit full screen':'Full screen';$('city-fullscreen').setAttribute('aria-pressed',String(!!on));engine?.resize();}
