function select(id,fly=false){if(fly&&referenceModel&&activeTown==='environment'&&id!=='environment'&&townProfiles[id]){openTown(id);return;}if(!worldNodes.some(n=>n.id===id))return;if(focusedIds&&!focusedIds.has(id)){if(lessonIndex!==null)entireK8sTown();focusedIds.add(id);engine?.setLearning([...focusedIds],referenceModel?currentProfile().layout:lessonIndex===null?null:learningLayouts[k8sLessons[lessonIndex].id]);}if(referenceModel&&fly)$('world-workspace').classList.add('inspector-open');selected=id;const district=$('city-district').value;if(!focusedIds&&district&&district!=='all'&&!ancestors(worldNodes,id).some(n=>n.id===district))resetDistrict();renderInspector();renderTree();if(engine){engine.selected=id;engine.dirty=true;if(fly)engine.focus(id);}const node=worldNodes.find(n=>n.id===id);$('world-status').textContent=engine?`Inspecting ${node.label} · modeled educational data`:`Selected ${node.label}. The text explorer works while 3D loads.`;}
