function renderTree(){const district=$('city-district').value;const matches=searchWorld(worldNodes,$('world-search').value).filter(n=>focusedIds?focusedIds.has(n.id):!district||district==='all'||ancestors(worldNodes,n.id).some(a=>a.id===district));$('world-search-count').textContent=focusedIds?`${matches.length} / ${focusedIds.size} components in this view`:`${matches.length} / ${worldNodes.length} components and features`;$('world-tree').replaceChildren(...matches.map(n=>{const b=el('button',undefined,'world-tree-item'+(n.minor?' minor':'')+(n.id===selected?' selected':''));const depth=focusedIds?ancestors(worldNodes,n.id).filter(a=>focusedIds.has(a.id)).length-1:ancestors(worldNodes,n.id).length-1;b.style.paddingLeft=(7+Math.min(depth,5)*11)+'px';b.append(el('span',(n.minor?'· ':'')+n.label));if(!n.minor)b.append(el('small',n.kind.toUpperCase()));b.setAttribute('aria-current',n.id===selected?'true':'false');b.addEventListener('click',()=>select(n.id,true));return b;}));if(!matches.length)$('world-tree').append(el('p','No matching modeled feature. See the scope list for what is included.'));}
function renderFlow(){const current=flow(),s=current.steps[stepIndex];$('world-transport-detail').textContent=transportDetails(s,worldNodes);$('world-boundary-detail').textContent=boundaryPath(worldNodes,s.from)+' → '+boundaryPath(worldNodes,s.to);$('world-flow').value=flowId;$('world-step-kind').textContent=s.kind.toUpperCase();$('world-step-title').textContent=s.title;$('world-step-text').textContent=s.text;$('world-step-packet').textContent=s.packet;$('world-step-counter').textContent=`Step ${stepIndex+1} of ${current.steps.length} · ${worldNodes.find(n=>n.id===s.from).label} → ${worldNodes.find(n=>n.id===s.to).label}`;$('world-prev').disabled=stepIndex===0;$('world-next').disabled=!canStepWorld(current,stepIndex,failureKey,worldFailures);$('world-flow').disabled=!!failureKey;$('city-flow-select').disabled=!!failureKey;$('world-step-list').replaceChildren(...current.steps.map((s,i)=>{const li=el('li'),b=el('button',`${s.title} — ${s.kind}`);b.addEventListener('click',()=>{pause();goStep(i);});li.append(b);return li;}));engine?.setFlow(flowId,stepIndex,activeFailure());$('city-flow-label').textContent='Guided flow';$('city-flow-select').value=flowId;$('city-step-title').textContent=s.title;$('city-step-text').textContent=s.text;$('city-packet').textContent=s.kind+' · '+s.packet;$('city-step-count').textContent=$('world-step-counter').textContent;$('city-back').disabled=stepIndex===0;$('city-forward').disabled=$('world-next').disabled;$('k8s-strip-title').textContent=s.title;$('k8s-strip-kind').textContent=`${stepIndex+1} / ${current.steps.length} · ${s.kind}`;$('k8s-strip-text').textContent=s.text;$('k8s-prev-step').disabled=stepIndex===0;$('k8s-next-step').disabled=$('world-next').disabled;if(requestState)renderRequest();}

function goStep(index){if(requestState){requestState=moveRequest(requestState,index);index=requestState.step;}resetDistrict();const current=flow();stepIndex=Math.max(0,Math.min(index,current.steps.length-1));const f=worldFailures[failureKey];if(f&&flowId===f.flow&&stepIndex>f.blockedStep)stepIndex=f.blockedStep;renderFlow();select(current.steps[stepIndex].to,$('world-follow').checked&&lessonIndex===null&&!referenceModel);}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>{if(!playing)return;if(requestState?.fault&&stepIndex>=requestFaults[requestState.fault].stop){pause();return;}if(!canStepWorld(flow(),stepIndex,failureKey,worldFailures)){pause();return;}goStep(stepIndex+1);if(stepIndex===flow().steps.length-1)pause();else schedule();},6000);}
async function loadEngine(){if(engine){engine.setActive(active&&!document.hidden);return;}if(loading)return loading;$('world-status').textContent='Loading local 3D engine · text exploration is already available';loading=(async()=>{try{const {KubernetesWorld}=await import('./world-scene.js');engine=new KubernetesWorld($('world-canvas'),$('world-labels'),{onSelect:select,onStep:index=>{pause();flowId=currentProfile().flowId;goStep(index);$('world-flow-details').open=true;},onView:view=>{$('world-level').textContent=view.distance>70?'COMPLETE CITY VIEW':view.distance>25?'DISTRICT VIEW':view.distance>16?'CLUSTER / NODE VIEW':view.distance>6?'POD / CONTAINER VIEW':'SMALL FEATURE VIEW';$('world-map-position').style.left=Math.max(2,Math.min(98,(view.target[0]+58)/116*100))+'%';$('world-map-position').style.top=Math.max(2,Math.min(98,(view.target[2]+70)/140*100))+'%';},onScanProgress:({progress,count,total,latest,found})=>{$('city-scan-progress').value=Math.round(progress*100);$('city-discovery-count').textContent=`${count} / ${total} modeled elements revealed`;if(found.length!==$('city-found-list').children.length){$('city-found-list').replaceChildren(...found.map(id=>{const b=el('button',worldNodes.find(n=>n.id===id).label);b.addEventListener('click',()=>{resetDistrict();select(id,true);});return b;}));}if(latest){discoveredId=latest.id;$('city-discovery').hidden=false;$('city-discovery').textContent='Detected: '+latest.label+' · inspect →';}},onScanComplete:()=>{$('world-status').textContent=`Scan complete · ${worldNodes.length-1} modeled elements. Select a discovery to learn its role.`;$('world-scan').disabled=false;},onError:message=>{$('world-error').hidden=false;$('world-error').textContent=message;pause();}});engine.setDetail($('world-detail').checked);if($('world-explode').dataset.enabled==='true')engine.setExploded(true);engine.setDistrict($('city-district').value==='all'?null:$('city-district').value);engine.selected=selected;engine.setTownProfile(currentProfile());engine.setReferenceMode(referenceModel);engine.setModelAnimation(modelMotion);if(focusedIds){engine.setLearning([...focusedIds],referenceModel?currentProfile().layout:lessonIndex===null?null:learningLayouts[k8sLessons[lessonIndex].id]);engine.frameLearning();}else engine.focus(selected,true);engine.setFlow(flowId,stepIndex,activeFailure());if(requestState){engine.setTeaching(true);engine.setFocusFlow($('teach-focus').checked);engine.setBoundaries($('teach-boundaries').checked?requestBoundaries:[]);};engine.setActive(active&&!document.hidden);$('world-error').hidden=true;$('world-status').textContent='Drag in any direction · scroll/pinch to zoom · select to inspect';}catch(error){$('world-error').hidden=false;$('world-error').textContent='3D could not start. This view requires WebGL2 and hardware acceleration. The searchable hierarchy, explanations, flow steps and failure exercises still work. Reload the page to retry. Details: '+String(error.message||error);$('world-status').textContent='Text explorer active · 3D unavailable';}finally{loading=null;}})();return loading;}
export function setWorldActive(value){active=value;if(!initialized)return;if(value)loadEngine();else {pause();if(pageFullscreen)setPageFullscreen(false);engine?.setActive(false);}}
