 $('coverage-town').replaceChildren(...coverageTowns().map(id=>{const o=el('option',townProfiles[id].label);o.value=id;return o;}));$('coverage-town').value='cluster';$('coverage-town').addEventListener('change',renderCoverage);renderCoverage();
